from typing import List
from bisect import bisect_right

class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        intervals_with_idx = [(intervals[i][0], intervals[i][1], intervals[i][2], i) for i in range(n)]
        intervals_with_idx.sort(key=lambda x: x[0])
        lefts = [x[0] for x in intervals_with_idx]

        # dp[i][k] = (max_weight, lex_smallest_sorted_index_list) using at most k
        # intervals from positions i..n-1 (in sorted-by-left order).
        dp = [[(0, []) for _ in range(5)] for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            l, r, w, idx = intervals_with_idx[i]
            # First index with left strictly greater than r (no shared boundary).
            next_i = bisect_right(lefts, r)

            # k = 0: always (0, [])
            for k in range(1, 5):
                w1, list1 = dp[i + 1][k]            # skip current
                prev_w, prev_list = dp[next_i][k - 1]
                w2 = w + prev_w                     # take current
                list2 = sorted(prev_list + [idx])

                if w1 > w2:
                    dp[i][k] = (w1, list1)
                elif w2 > w1:
                    dp[i][k] = (w2, list2)
                else:
                    if list1 <= list2:
                        dp[i][k] = (w1, list1)
                    else:
                        dp[i][k] = (w2, list2)

        return dp[0][4][1]
